xql_query:
// ============================================================
// Rule: WIN_AD Multiple User Deletions
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_AD Multiple User Deletions.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Technique: T1485 - Data Destruction

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: padronizar comparações e evitar perda de eventos por variações de caixa
config case_sensitive = false

// Fonte de dados: telemetria do agente (inclui Windows Security Event Log)
| dataset = xdr_data

// Filtro: restringe a eventos do Windows Event Log
// Event ID 4726 = "A user account was deleted" (exclusão de conta no AD/Windows)
| filter event_type = ENUM.EVENT_LOG
| filter action_evtlog_event_id = 4726

// Extração/normalização de campos do evento 4726 (Security)
// - Subject*: executor (quem deletou)
// - Target*: alvo (conta deletada)
| alter
    SubjectUserName   = action_evtlog_data_fields -> SubjectUserName,    // Usuário executor da exclusão
    SubjectDomainName = action_evtlog_data_fields -> SubjectDomainName,  // Domínio do executor
    TargetUserName    = action_evtlog_data_fields -> TargetUserName,     // Conta deletada
    TargetDomainName  = action_evtlog_data_fields -> TargetDomainName,   // Domínio da conta deletada
    TargetSid         = action_evtlog_data_fields -> TargetSid           // SID da conta deletada

// Agrupamento temporal: consolida eventos em janelas de 1 hora para identificar deleção em massa
| bin _time span = 1h

// Agregação: contabiliza quantas contas distintas foram deletadas na janela
// - users_deleted: número de usuários distintos deletados
// - deleted_users/deleted_sids: evidências para investigação
| comp
    count_distinct(TargetUserName) as users_deleted,
    values(TargetUserName) as deleted_users,
    values(TargetSid) as deleted_sids
  by _time, agent_hostname, SubjectDomainName, SubjectUserName

// Threshold: dispara quando houver exclusão em massa (ajuste conforme baseline do ambiente)
| filter users_deleted >= 5

// Ordenação: destaca os maiores volumes de exclusão
| sort desc users_deleted

| filter (SubjectUserName != """<IDENTITY_PROVISIONING_ACCOUNT>""") 
| filter (`deleted_users` not contains """lenovo_tmp""")
